class Solution {
    public String decodeString(String s) {
        Deque<String> prevs = new ArrayDeque<>();
        Deque<Integer> counts = new ArrayDeque<>();
        StringBuilder cur = new StringBuilder();
        int k = 0;
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) {
                k = k * 10 + (c - '0');                 // 数字可能不止一位
            } else if (c == '[') {
                prevs.push(cur.toString());             // 存档：括号外的前缀和重复次数
                counts.push(k);
                cur = new StringBuilder();
                k = 0;
            } else if (c == ']') {
                String inner = cur.toString().repeat(counts.pop());
                cur = new StringBuilder(prevs.pop()).append(inner);    // 展开后接回前缀
            } else {
                cur.append(c);
            }
        }
        return cur.toString();
    }
}

