class Solution {
public:
    string decodeString(string s) {
        vector<pair<string, int>> stack;
        string cur;
        int k = 0;
        for (char c : s) {
            if (isdigit(c)) {
                k = k * 10 + (c - '0');                 // 数字可能不止一位
            } else if (c == '[') {
                stack.push_back({cur, k});              // 存档：括号外的前缀和重复次数
                cur = "";
                k = 0;
            } else if (c == ']') {
                auto [prev, times] = stack.back();
                stack.pop_back();
                string inner;
                while (times--) inner += cur;
                cur = prev + inner;                     // 展开后接回前缀
            } else {
                cur += c;
            }
        }
        return cur;
    }
};

