func decodeString(s string) string {
	type saved struct {
		prev  string
		times int
	}
	stack, cur, k := []saved{}, "", 0
	for _, c := range s {
		if c >= '0' && c <= '9' {
			k = k*10 + int(c-'0') // 数字可能不止一位
		} else if c == '[' {
			stack = append(stack, saved{cur, k}) // 存档：括号外的前缀和重复次数
			cur, k = "", 0
		} else if c == ']' {
			top := stack[len(stack)-1]
			stack = stack[:len(stack)-1]
			cur = top.prev + strings.Repeat(cur, top.times) // 展开后接回前缀
		} else {
			cur += string(c)
		}
	}
	return cur
}

