class Solution {
public:
    string decodeString(string s) {
        regex inner("(\\d+)\\[([a-z]*)\\]");
        while (s.find('[') != string::npos) {
            string out;
            auto from = s.cbegin();
            smatch m;
            while (regex_search(from, s.cend(), m, inner)) {
                out += m.prefix().str();
                for (int k = stoi(m[1].str()); k > 0; k--) out += m[2].str();
                from = m[0].second;
            }
            out.append(from, s.cend());
            s = out;
        }
        return s;
    }
};

